export let LANG = "en";
export function setLang(l) { LANG = L.includes(l) ? l : "en"; document.documentElement.lang = LANG; document.documentElement.dir = LANG === "ar" ? "rtl" : "ltr"; }
export function t(k, v) {
  const row = S[k]; let s = row ? row[L.indexOf(LANG)] || row[0] : k;
  if (v) for (const key in v) s = s.split("{" + key + "}").join(v[key]);
  return s;
}
export function achDesc(id) { const r = AD[id]; return r ? (LANG === "ar" ? r[1] : r[0]) : ""; }
export function applyI18n(root = document) {
  root.querySelectorAll("[data-i]").forEach((el) => { el.textContent = t(el.dataset.i); });
  root.querySelectorAll("[data-ip]").forEach((el) => { el.placeholder = t(el.dataset.ip); });
  root.querySelectorAll("[data-ia]").forEach((el) => { el.setAttribute("aria-label", t(el.dataset.ia)); });
}
export const fmtNum = (n) => { try { return new Intl.NumberFormat(LANG === "ar" ? "ar-u-nu-latn" : LANG).format(Math.round(n)); } catch (_) { return String(Math.round(n)); } };
